import uniqid from 'uniqid'
import GitHubIcon from '@material-ui/icons/GitHub'
import LaunchIcon from '@material-ui/icons/Launch'
import './ProjectContainer.css'

export default function ProjectContainer({ project }){

  const getMediaPath = (filePath) => {
    if (!filePath) return ''
    return filePath.startsWith('http')
      ? filePath
      : `${process.env.PUBLIC_URL}/images/${filePath}`
  }

  return (
  <div className='project'>

    {/* Display project image screenshot */}
      {project.image && (
        <img
          src={getMediaPath(project.image)}
          alt={`${project.name} screenshot`}
          style={{ width: '100%', objectFit: 'cover' }}
        />
      )}

    <h3>{project.name}</h3>

    <p className='project__description'>{project.description}</p>
    {project.stack && (
      <ul className='project__stack'>
        {project.stack.map((item) => (
          <li key={uniqid()} className='project__stack-item'>
            {item}
          </li>
        ))}
      </ul>
    )}

    {project.sourceCode && (
      <a
        href={project.sourceCode}
        aria-label='source code'
        className='link link--icon'
      >
        <GitHubIcon />
      </a>
    )}

    {project.livePreview && (
      <a
        // href={project.livePreview}
        // aria-label='live preview'
        // className='link link--icon'
        href={`${process.env.PUBLIC_URL}/images/${project.livePreview}`}
        target='_blank'
        rel='noreferrer'
        className='link link--icon'
        aria-label='live preview'
      >
        <LaunchIcon />
      </a>
    )}
  </div>
  )
}
